INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 20, 'theory', 'Quiz: oVirt storage');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 0, 'Which host, in the classic scheme, may change volume metadata (create, delete, extend volumes) in a data center?', '["Any host that grabbed a file lock first", "The host that runs the engine", "The single host holding the Storage Pool Manager role", "All hosts in turn through the engine"]', 2, 'The metadata are shared and the storage does not resolve write conflicts, so there is one writer: the SPM. The engine appoints it, and a sanlock lease provides the exclusivity.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 1, 'What is a block storage domain at the LVM level?', '["A volume group whose name equals the domain UUID", "A single physical volume without a layout", "A directory on an ext4 file system", "A single logical volume with all the disks inside it"]', 0, 'The domain is a volume group, and the service areas and disk volumes are separate logical volumes in it. As in a file domain, one disk is not mixed with others.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 2, 'Where is a volume''s link to its parent in the chain recorded in a block domain?', '["In a .lease file next to the volume", "In the ids area of the domain", "Only in the engine''s database", "In the PU_ tag of the logical volume and in the volume metadata"]', 3, 'The PU_ tag keeps the parent identifier right on the logical volume, and the same value lies in the volume''s slot in metadata. So the chain can be rebuilt even without the engine''s database.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 3, 'What are sanlock leases used for in oVirt?', '["To encrypt traffic between the engine and a host", "So that only one host at a time owns the SPM role, a volume, or a machine", "To compress qcow2 images", "To determine the start order of machines"]', 1, 'A lease is a record on shared storage that its owner keeps renewing. If renewal stops, the lease expires and the resource can be given to another host without the risk of double ownership.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 4, 'What happens with default settings if the free space in a domain is below the critical threshold (5 GB)?', '["The domain will delete the oldest snapshots itself", "The domain becomes read-only for running machines", "New disks and snapshots cannot be created on it", "The engine shuts down all machines with disks on this domain"]', 2, 'The critical threshold blocks operations that need new space. Running machines keep running, and the engine will not delete anything automatically.');
